<script setup>
import { onMounted, reactive, ref } from 'vue'; import { setSession } from '../stores/ui'; const form=reactive({name:'',phone:'',city:'',state:'',birth_date:'',housing_type:null,has_other_pets:false,household_description:''}),saved=ref(false),loading=ref(false);const csrf=document.querySelector('meta[name="csrf-token"]')?.getAttribute('content')||'';const headers={Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':csrf};onMounted(async()=>{const data=await (await fetch('/api/profile',{credentials:'same-origin',headers})).json();Object.assign(form,data.user,{birth_date:data.user.birth_date?.slice(0,10)||''})});async function save(){loading.value=true;const response=await fetch('/api/profile',{method:'PUT',credentials:'same-origin',headers,body:JSON.stringify(form)});const data=await response.json();loading.value=false;setSession(data.user);saved.value=true;setTimeout(()=>saved.value=false,3000)}
</script><template><v-container class="py-10" style="max-width:1000px"><div class="section-kicker">PERFIL DE ADOTANTE</div><h1 class="text-h4 font-weight-bold mb-2">Conte sobre o seu lar</h1><p class="text-medium-emphasis mb-7">Esses dados ajudam a ONG a entender se o perfil do pet combina com sua família.</p><v-alert v-if="saved" type="success" variant="tonal" class="mb-5">Perfil atualizado com sucesso.</v-alert><v-card rounded="xl" elevation="2"><v-card-title class="pa-6">Informações pessoais</v-card-title><v-card-text class="px-6"><v-form @submit.prevent="save"><v-row><v-col cols="12" md="6"><v-text-field v-model="form.name" label="Nome completo" variant="outlined"/></v-col><v-col cols="12" md="6"><v-text-field v-model="form.phone" label="Telefone" variant="outlined"/></v-col><v-col cols="12" md="6"><v-text-field v-model="form.city" label="Cidade" variant="outlined"/></v-col><v-col cols="12" md="3"><v-text-field v-model="form.state" label="UF" maxlength="2" variant="outlined"/></v-col><v-col cols="12" md="3"><v-text-field v-model="form.birth_date" label="Data de nascimento" type="date" variant="outlined"/></v-col><v-col cols="12" md="6"><v-select v-model="form.housing_type" :items="['Casa com quintal','Casa sem quintal','Apartamento']" label="Tipo de moradia" variant="outlined"/></v-col><v-col cols="12" md="6"><v-checkbox v-model="form.has_other_pets" label="Tenho outros animais em casa" color="primary"/></v-col><v-col cols="12"><v-textarea v-model="form.household_description" label="Conte sobre sua rotina, família e espaço disponível" variant="outlined"/></v-col></v-row><v-btn type="submit" :loading="loading" color="primary" size="large">Salvar perfil</v-btn></v-form></v-card-text></v-card></v-container></template>
